I'm stopping the investigation here. The one fault I can tie to user impact with confidence is ts-inside-payment-service, which restarted at about 07:06 and caused the 503s. The travel/route/seat slowdown is real, but I could not pin it to a specific fault in the budget, so I have not named it.

```json
{
  "root_causes": [
    {
      "service": "ts-inside-payment-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'norm' p, attr_k8s_pod_name pod, min(value) mn, max(value) mx FROM normal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-inside-payment%' GROUP BY 1,2 UNION ALL SELECT 'abn', attr_k8s_pod_name, min(value), max(value) FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-inside-payment%' GROUP BY 1,2",
          "claim": "inside-payment container restart counter goes from 0 in the normal period to 1 in the abnormal period, so it restarted."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) t, count(*) n, sum(CASE WHEN attr_http_response_status_code=503 THEN 1 ELSE 0 END) n503 FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/inside_pay_service/inside_payment' GROUP BY 1 ORDER BY 1",
          "claim": "110 of 112 ui-dashboard POST inside_payment calls returned 503 in the 07:06 minute, then recovered to 200."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, count(*) n FROM abnormal_traces WHERE span_name='POST /api/v1/inside_pay_service/inside_payment' GROUP BY 1,2 UNION ALL SELECT 'norm', service_name, count(*) FROM normal_traces WHERE span_name='POST /api/v1/inside_pay_service/inside_payment' GROUP BY 1,2",
          "claim": "Only 15 inside-payment server spans exist in the abnormal period against 125 ui-dashboard calls, so most requests never reached the service."
        },
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) t, round(avg(CASE WHEN metric='k8s.pod.cpu.usage' THEN value END),3) cpu_usage, round(avg(CASE WHEN metric='k8s.pod.cpu_limit_utilization' THEN value END),3) cpu_lim FROM abnormal_metrics WHERE service_name='ts-inside-payment-service' GROUP BY 1 ORDER BY 1",
          "claim": "Inside-payment CPU spikes to about 1.8 cores at 07:06 during the restart, then falls back to idle; the container never reaches its limit."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE span_name='POST /api/v1/inside_pay_service/inside_payment' GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "The ui-dashboard user-facing POST returns 503 at about 457 ms average, matching the inside-payment failure window."
        }
      ]
    }
  ]
}
```

